// Mock-file read tests for NetcdfSharp.Grib.
// The mock files are generated by ..\generate_mock_data.py (output: ..\mock-datasets, gitignored).
// If the data is absent, tests pass with a message so the suite stays green without the (generated)
// binary test data; run `python generate_mock_data.py` (from the repo root) to produce it.
//
// Mirrors the scanning sanity checks of netcdf-java:
//   grib/src/test/java/ucar/nc2/grib/grib1/TestGrib1Records.java
//   grib/src/test/java/ucar/nc2/grib/grib2/TestGrib2Records.java


using System;
using System.IO;
using NetcdfSharp.ucar.nc2.grib.grib1;
using NetcdfSharp.ucar.nc2.grib.grib2;
using NetcdfSharp.ucar.unidata.io;
using Xunit;

namespace NetcdfSharp.ucar.nc2.grib
{

	/// <summary>
	/// End-to-end read of the generated mock GRIB1/GRIB2 files:
	/// scan records, then unpack each record's data.
	/// </summary>
	public class GribRecordReadTests
	{
		private static string MockPath(string name)
		{
			string dir = AppContext.BaseDirectory;
			while (dir != null)
			{
				string candidate = Path.Combine(dir, "mock-datasets");
				if (Directory.Exists(candidate))
				{
					return Path.Combine(candidate, name);
				}
				dir = Path.GetDirectoryName(dir);
			}
			return null;
		}

		[Fact]
		public void ScanAndReadMockGrib1File()
		{
			string fp = MockPath("test_grib1.grb");
			if (fp == null || !File.Exists(fp))
			{
				return; // run generate_mock_data.py
			}

			RandomAccessFile raf = new RandomAccessFile(fp, "r");
			try
			{
				raf.order(RandomAccessFile.BIG_ENDIAN);
				raf.seek(0);

				Grib1RecordScanner scanner = new Grib1RecordScanner(raf);
				int count = 0;
				while (scanner.hasNext())
				{
					Grib1Record gr = scanner.next();
					if (gr == null)
					{
						break;
					}
					count++;

					Assert.NotNull(gr.GDS);
					Assert.NotNull(gr.PDSsection);
					Assert.NotNull(gr.ReferenceDate);

					float[] data = gr.readData(raf);
					Assert.NotNull(data);
					Assert.True(data.Length > 0, "expected unpacked data");
					Assert.Equal(gr.GDS.Nx * gr.GDS.Ny, data.Length);
				}
				Assert.True(count >= 1, "expected at least one GRIB1 record");
			}
			finally
			{
				raf.close();
			}
		}

		[Fact]
		public void ScanAndReadMockGrib2File()
		{
			string fp = MockPath("test_grib2.grb2");
			if (fp == null || !File.Exists(fp))
			{
				return; // run generate_mock_data.py
			}

			RandomAccessFile raf = new RandomAccessFile(fp, "r");
			try
			{
				raf.order(RandomAccessFile.BIG_ENDIAN);
				raf.seek(0);

				Grib2RecordScanner scanner = new Grib2RecordScanner(raf);
				int count = 0;
				while (scanner.hasNext())
				{
					Grib2Record gr = scanner.next();
					if (gr == null)
					{
						break;
					}
					count++;

					Assert.NotNull(gr.GDS);
					Assert.NotNull(gr.PDSsection);
					Assert.NotNull(gr.ReferenceDate);

					float[] data = gr.readData(raf);
					Assert.NotNull(data);
					Assert.True(data.Length > 0, "expected unpacked data");
					Assert.Equal(gr.GDS.Nx * gr.GDS.Ny, data.Length);
				}
				Assert.True(count >= 1, "expected at least one GRIB2 record");
			}
			finally
			{
				raf.close();
			}
		}
	}
}
